<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'
import { useRoute } from 'vue-router'
import { get, post } from '@/api/request'
import LocalSession from '@/features/versions/LocalSession.vue'
import { getLocalContext, errorMessage, mutationAttempt, errorCode } from '@/features/versions/api'
import type { LocalContext } from '@/features/versions/types'
interface Calculation {id:string;aggregateScore:number;passed:boolean;algorithmVersion:string;inputSubmissionIds:string[]}
interface Checkpoint {id:string;agreementScore:number;calculationId:string}
interface View {canWrite:boolean;canConfirm:boolean;scope:{startOffset:number;endOffset:number};scopeText:string;submissions:{id:string;attemptNumber:number;submittedById:string}[];calculations:Calculation[];checkpoints:Checkpoint[]}
const route=useRoute(), context=ref<LocalContext>(), caseId=ref(String(route.query.caseId||'')), view=ref<View>(), loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),cuts=ref(''),reason=ref(''),calculationId=ref(''),checkpointId=ref(''),draftId=ref('')
const attempt=mutationAttempt<{op:string;body:object}>(), pending=ref(false)
const drafts=computed(()=>context.value?.drafts.filter(d=>d.taskDocumentId===caseId.value&&d.status==='ACTIVE')||[])
const prefix=()=>`/api/local/member-d/segmentation/cases/${caseId.value}`
async function load(){loading.value=true;error.value='';view.value=undefined;try{if(!import.meta.env.DEV)throw new Error('切割试行面板仅在本地开放，正式接口待团队评审');context.value=await getLocalContext();caseId.value ||= context.value.taskDocuments[0]?.id||'';if(!caseId.value)throw new Error('没有已分配案例');view.value=await get<View>(prefix(),undefined,{baseURL:''});}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function boundaries(){if(!view.value)throw new Error('请先加载案例');const raw=cuts.value.trim();if(raw&&!/^\d+(?:[，,\s]+\d+)*$/.test(raw))throw new Error('切割位置应为整数，以逗号或空格分隔');const ends=[...(raw?raw.split(/[，,\s]+/).map(Number):[]),view.value.scope.endOffset];let start=view.value.scope.startOffset;return ends.map(end=>{const row={startOffset:start,endOffset:end};start=end;return row})}
async function execute(op:string){if(busy.value)return;busy.value=true;error.value='';try{let body:object={},version=0;if(!pending.value){if(op==='submissions')body={boundaries:boundaries()};if(op==='checkpoints')body={calculationId:calculationId.value,unifiedBoundaries:boundaries(),reason:reason.value.trim()};if(op==='draft-binding'){const draft=drafts.value.find(d=>d.id===draftId.value);if(!draft)throw new Error('请选择本人草稿');body={draftId:draft.id,checkpointId:checkpointId.value};version=draft.recordVersion}}
const a=attempt.get({op,body},version);pending.value=true;await post(prefix()+'/'+a.body.op,a.body.body,{baseURL:'',headers:{'Idempotency-Key':a.key,...(a.body.op==='draft-binding'?{'If-Match':a.version}:{})}});attempt.reset();pending.value=false;notice.value='操作已保存，历史输入和计算记录保留';await load();}catch(e){error.value=errorMessage(e);if(errorCode(e)){attempt.reset();pending.value=false}}finally{busy.value=false}}
onMounted(load)
</script>
<template><LocalSession description="独立切割与统一关口试行；标注员只读取本人独立输入"/><div class="page-head"><div class="eyebrow">SEGMENTATION</div><h1 class="t-h1">独立切割与统一关口</h1><p class="muted">内部边界两两 F1 均值，严格大于 80% 才能确认。算法 trial-1 仍待团队评审。</p></div>
<div class="card card-body row"><select class="select" aria-label="案例" v-model="caseId" :disabled="pending||busy" @change="load"><option v-for="d in context?.taskDocuments" :key="d.id" :value="d.id">{{ d.document.title }}</option></select><button class="btn btn-secondary" @click="load" :disabled="busy">刷新</button></div>
<div v-if="error" class="note danger" role="alert">{{ error }}</div><div v-if="notice" class="note accent">{{ notice }}</div><button v-if="pending&&!busy" class="btn btn-primary" @click="execute('retry')">重试相同操作</button><div v-if="loading" role="status">读取中…</div>
<div v-if="view" class="grid-2 panels"><div v-if="!view.canWrite" class="note warn readonly">当前案例已进入裁定或归档阶段，切割历史只读。</div><section class="card"><div class="card-head"><b>{{ view.canConfirm?'协商统一切割':'本人独立切割' }}</b></div><div class="card-body stack-3"><p class="text">{{ view.scopeText }}</p><p class="t-xs muted">完整范围 [{{ view.scope.startOffset }}, {{ view.scope.endOffset }})，位置使用原文 UTF-16 半开区间。</p><label for="cuts">内部切割位置，按从小到大填写，以逗号分隔</label><input id="cuts" class="input" v-model="cuts" placeholder="例如：20" :disabled="pending||busy||!view.canWrite"><p class="muted t-xs">起点和终点由系统补齐；不填表示范围内只有一个片段。</p><button v-if="!view.canConfirm" class="btn btn-primary" :disabled="busy||pending||!view.canWrite" @click="execute('submissions')">提交本人独立切割</button><template v-else><button class="btn btn-secondary" :disabled="busy||pending||!view.canWrite" @click="execute('calculations')">根据当前 N 人提交计算一致性</button><label>选择已通过的计算</label><select class="select" v-model="calculationId" :disabled="busy||pending||!view.canWrite"><option value="">请选择</option><option v-for="c in view.calculations.filter(c=>c.passed)" :key="c.id" :value="c.id">{{ c.id.slice(0,8) }} · {{ (c.aggregateScore*100).toFixed(2) }}%</option></select><label for="seg-reason">统一切割确认理由</label><textarea id="seg-reason" class="textarea" v-model="reason" :disabled="busy||pending||!view.canWrite"/><button class="btn btn-primary" :disabled="busy||pending||!view.canWrite||!calculationId||!reason.trim()" @click="execute('checkpoints')">确认统一关口</button></template></div></section>
<section class="card"><div class="card-head"><b>已保存记录</b></div><div class="card-body stack-3"><p>独立输入 {{ view.submissions.length }} 条（只展示当前身份可读记录）</p><p v-for="s in view.submissions" :key="s.id" class="mono t-xs">{{ s.id }} · 第 {{ s.attemptNumber }} 次</p><p v-for="c in view.calculations" :key="c.id">{{ c.id.slice(0,8) }} · {{ (c.aggregateScore*100).toFixed(2) }}% · {{ c.passed?'通过':'未通过' }}</p><p v-if="!view.checkpoints.length" class="muted">尚未生成真实输入的统一关口。</p><p v-for="c in view.checkpoints" :key="c.id" class="mono">{{ c.id }} · 已确认</p><template v-if="!view.canConfirm&&view.checkpoints.length"><label>本人草稿</label><select class="select" v-model="draftId"><option v-for="d in drafts" :key="d.id" :value="d.id">{{ d.id }}</option></select><label>确认关口</label><select class="select" v-model="checkpointId"><option v-for="c in view.checkpoints" :key="c.id" :value="c.id">{{ c.id }}</option></select><button class="btn btn-secondary" :disabled="busy||pending||!view.canWrite||!draftId||!checkpointId" @click="execute('draft-binding')">将关口绑定本人草稿</button><p class="t-xs muted">绑定不会自动修改要素；要素边界仍须与统一切割一致，已提交版本保持原基准。</p></template></div></section></div></template>
<style scoped>.readonly{grid-column:1/-1}.panels{align-items:start;margin-top:20px}.note{margin:16px 0}.text{white-space:pre-wrap;line-height:2}.row{gap:12px}.mono{overflow-wrap:anywhere}.textarea{min-height:100px}@media(max-width:900px){.panels{grid-template-columns:1fr}}</style>
